"""
borecli/bore/handlers/error_pages.py

Branded HTML error pages returned to the browser when the
local application is unreachable, times out, or the tunnel
hits an unexpected internal error.

Kept as plain string templates (no Jinja/template engine
dependency) since these are only ever rendered once per
failed request, directly inside http_handler.py.
"""

# Logo embedded as a data URI so the page is fully self-contained --
# no static file serving required from the CLI process.
LOGO_DATA_URI = (
    "data:image/png;base64,"
)


def _page(title: str, heading: str, message: str, detail: str = "") -> str:
    """
    Shared page shell. `detail` is optional smaller text
    (e.g. the local port, or a technical hint) shown under
    the main message.
    """

    detail_html = f'<p class="detail">{detail}</p>' if detail else ""

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title}</title>
<style>
  :root {{
    --bh-black: #1c1c1c;
    --bh-charcoal: #292929;
    --bh-orange: #e56709;
    --bh-orange-soft: rgba(229, 103, 9, 0.35);
  }}

  * {{
    box-sizing: border-box;
  }}

  html, body {{
    height: 100%;
    margin: 0;
  }}

  body {{
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    padding: 24px;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                 Helvetica, Arial, sans-serif;
    background:
      radial-gradient(circle at 20% 15%, rgba(229, 103, 9, 0.10), transparent 45%),
      radial-gradient(circle at 85% 85%, rgba(229, 103, 9, 0.08), transparent 50%),
      var(--bh-black);
    color: #e8e8e8;
  }}

  .card {{
    width: 100%;
    max-width: 460px;
    background: var(--bh-charcoal);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 16px;
    padding: 40px 36px 34px;
    text-align: center;
    box-shadow:
      0 20px 60px rgba(0, 0, 0, 0.45),
      0 0 0 1px rgba(255, 255, 255, 0.02);
  }}

  .logo {{
    width: 84px;
    height: auto;
    margin-bottom: 22px;
    filter: drop-shadow(0 4px 14px rgba(229, 103, 9, 0.25));
  }}

  .status-dot {{
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--bh-orange);
    background: rgba(229, 103, 9, 0.12);
    border: 1px solid var(--bh-orange-soft);
    padding: 6px 14px;
    border-radius: 999px;
    margin-bottom: 20px;
  }}

  .status-dot::before {{
    content: "";
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--bh-orange);
    box-shadow: 0 0 0 0 var(--bh-orange-soft);
    animation: pulse 1.8s ease-out infinite;
  }}

  @keyframes pulse {{
    0%   {{ box-shadow: 0 0 0 0 rgba(229, 103, 9, 0.55); }}
    70%  {{ box-shadow: 0 0 0 8px rgba(229, 103, 9, 0); }}
    100% {{ box-shadow: 0 0 0 0 rgba(229, 103, 9, 0); }}
  }}

  h1 {{
    margin: 0 0 10px;
    font-size: 21px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.01em;
  }}

  p {{
    margin: 0 0 6px;
    font-size: 14.5px;
    line-height: 1.55;
    color: #b8b8b8;
  }}

  p.detail {{
    margin-top: 14px;
    font-size: 12.5px;
    color: #7a7a7a;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  }}

  .divider {{
    width: 40px;
    height: 3px;
    background: var(--bh-orange);
    border-radius: 2px;
    margin: 18px auto 20px;
  }}

  .brand-footer {{
    margin-top: 28px;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #5a5a5a;
  }}

  .brand-footer span {{
    color: var(--bh-orange);
  }}
</style>
</head>
<body>
  <div class="card">
    <img class="logo" src="{LOGO_DATA_URI}" alt="BoreHook">
    <div class="status-dot">{heading}</div>
    <div class="divider"></div>
    <h1>{title}</h1>
    <p>{message}</p>
    {detail_html}
    <div class="brand-footer">Bore<span>Hook</span> Tunnel</div>
  </div>
</body>
</html>"""


def tunnel_unreachable_page(local_port: int | None = None) -> str:
    """
    Shown when the CLI cannot open a connection to the
    local application (connection refused / not running).
    """

    detail = f"Expected a local server on 127.0.0.1:{local_port}" if local_port else ""

    return _page(
        title="Tunnel Unreachable",
        heading="Waiting for local server",
        message=(
            "Your local application isn\'t responding on this tunnel. "
            "Make sure it\'s running, then refresh this page."
        ),
        detail=detail,
    )


def tunnel_timeout_page() -> str:
    """
    Shown when the local application accepted the connection
    but took too long to respond.
    """

    return _page(
        title="Request Timed Out",
        heading="Local server is slow",
        message=(
            "Your local application didn\'t respond in time. "
            "It may be under heavy load, or stuck processing this request."
        ),
    )


def tunnel_internal_error_page() -> str:
    """
    Shown for unexpected BoreHook-side failures.
    """

    return _page(
        title="Tunnel Error",
        heading="Something went wrong",
        message=(
            "BoreHook hit an unexpected error while forwarding this request. "
            "Try again, and check your CLI logs for details."
        ),
    )